import {readFile,writeFile} from 'node:fs/promises';
const handler=await readFile('supabase/functions/stripe-sandbox/handler.ts','utf8');
const config=JSON.parse(await readFile('supabase/billing/stripe-sandbox-prices.json','utf8'));
const code=handler
 .replace("import configuration from '../../billing/stripe-sandbox-prices.json' with {type:'json'};",'const configuration='+JSON.stringify(config,null,2)+';');
await writeFile('supabase/stripe-sandbox-function.ts',
 '// Generated by scripts/build-stripe-sandbox-function.mjs; copy this entire file into the Supabase editor.\n'+
 "import {createClient} from 'npm:@supabase/supabase-js@2.118.0';\n"+code+
 '\nDeno.serve(createStripeSandboxHandler({createClient,env:(name:string)=>Deno.env.get(name)}));\n');
console.log('Built sandbox-only Stripe connection checker; no credentials included.');
